import re

def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,

    Parameters:
    a (int, float or str): The first value to compare
    b (int, float or str): The second value to compare

    Returns:
    int, float or str: The larger value in its original type, or None if the values are equal
    """

    # Try to convert both inputs to float
    try:
        a_float = float(a)
        b_float = float(b)

        # If both inputs can be converted to float, compare them directly
        if a_float > b_float:
            return a_float
        elif a_float < b_float:
            return b_float
        else:
            return None

    # If inputs cannot be converted to float, check if they are strings
    except ValueError:
        # If both inputs are strings, use regular expression to replace comma with dot and convert to float
        if isinstance(a, str) and isinstance(b, str):
            a = float(a.replace(',', '.'))
            b = float(b.replace(',', '.'))
            if a > b:
                return a
            elif a < b:
                return b
            else:
                return None
        # If only one input is a string, convert it to float and compare
        elif isinstance(a, str):
            return float(a.replace(',', '.')) if a > b else (b if b > a else None)
        elif isinstance(b, str):
            return float(b.replace(',', '.')) if a > b else (a if a > b else None)
        # If neither input is a string, assume they are integers and compare
        else:
            return a if a > b else (b if b > a else None)
